  const cursor=new THREE.Vector2(),raycaster=new THREE.Raycaster();let pointerIn=false,hoverArmed=false,selected=0,theme=0,frame=0,disposed=false,down=null,zoomTarget=null,lastTime=null;const reduced=matchMedia('(prefers-reduced-motion: reduce)');
  const placeMarkers=()=>{const total=archive.works[theme].photos.length;markers.forEach((s,i)=>{s.visible=i<total;const a=i*Math.PI*2/Math.max(total,1)+.35+theme*.8,r=4.4+i*.55;s.position.set(Math.cos(a)*r,1.1+i*.85,Math.sin(a)*r);s.userData.sprite.scale.setScalar(i===selected?.48:.36);});};
